import fc from "fast-check";
import { describe, expect, it } from "vitest";
import {
  type AgentEvent,
  type AgentMachineMsg,
  type AgentState,
  type AgentTurn,
  agentEvents,
  createAgent,
  type Schema,
  type ToolCall,
} from "./index";

// ---------------------------------------------------------------------------
// Promise: every note an agent makes is reported exactly once.
//
// A host that embeds the agent's verbs by hand folds its own Msgs too, and
// those leave the agent slice untouched. Projecting such a transition must not
// report the previous door's notes again: the stream a host sees, with any
// number of parent-only folds interleaved, is the stream the doors alone made,
// and that stream holds one event per note.
// ---------------------------------------------------------------------------

type Purpose = "act";
interface Outputs extends Record<Purpose, AgentTurn> {
  readonly act: AgentTurn;
}
type ToolCmd = { readonly type: "run_tool" } & ToolCall;
type M = AgentMachineMsg<Purpose, Outputs, string>;
type S = AgentState<string, Purpose, Outputs, string>;

const turnSchema: Schema<AgentTurn> = { parse: (v) => v as AgentTurn };

function makeAgent() {
  return createAgent<string, Purpose, Outputs, string, ToolCmd>({
    stages: ["only"],
    model: () => ({
      withStructuredOutput<T>(_s: Schema<T>) {
        return { invoke: async (): Promise<T> => ({}) as T };
      },
    }),
    schemas: { act: turnSchema },
    turnOf: () => "act",
    toolOf: (c) => ({ type: "run_tool", ...c }),
    rng: () => 0,
  });
}

// A parent's own Msgs, which the agent has never heard of.
const hostAgentMsg = { type: "host_agent_step" } as unknown as M;
const hostTick = { type: "host_tick" } as unknown as M;

// One scenario: some tool-asking turns (each call ok or failing), then an
// answer that ends the run; after every door, some parent-only folds.
const scenario = fc.record({
  toolTurns: fc.array(fc.array(fc.boolean(), { minLength: 1, maxLength: 3 }), {
    maxLength: 3,
  }),
  folds: fc.array(fc.nat({ max: 3 }), { minLength: 40, maxLength: 40 }),
});

type Step = (s: S) => S;

function stepsOf(
  agent: ReturnType<typeof makeAgent>,
  toolTurns: readonly (readonly boolean[])[],
): Step[] {
  let at = 0;
  const tick = () => ++at;
  const steps: Step[] = [(s) => agent.start(s, "run-1", tick())[0]];
  toolTurns.forEach((calls, t) => {
    const toolCalls: ToolCall[] = calls.map((_, i) => ({
      callId: `t${t}c${i}`,
      name: "search",
      args: { i },
    }));
    steps.push((s) => agent.turn(s, { content: "ask", toolCalls }, tick())[0]);
    calls.forEach((ok, i) => {
      const callId = `t${t}c${i}`;
      steps.push((s) =>
        ok
          ? agent.toolOk(s, callId, `ok:${callId}`, tick())[0]
          : agent.toolErr(s, callId, "boom", tick())[0],
      );
    });
  });
  steps.push(
    (s) => agent.turn(s, { content: "done", toolCalls: [] }, tick())[0],
  );
  return steps;
}

/** Drive the doors, projecting each one and `folds[i]` parent folds after it. */
function drive(
  toolTurns: readonly (readonly boolean[])[],
  folds: readonly number[],
) {
  const agent = makeAgent();
  const project = agentEvents<string, Purpose, Outputs, string>();
  const stream: AgentEvent<string>[] = [];
  const fromFolds: AgentEvent<string>[] = [];
  let s: S = agent.init();
  stepsOf(agent, toolTurns).forEach((step, i) => {
    s = step(s);
    stream.push(...project(hostAgentMsg, s));
    for (let f = 0; f < (folds[i] ?? 0); f++) {
      // The parent folds its own Msg; the agent slice is left as it was.
      const out = project(hostTick, s);
      fromFolds.push(...out);
      stream.push(...out);
    }
  });
  return { stream, fromFolds, settled: agent.isSettled(s) };
}

describe("every note an agent makes is reported exactly once", () => {
  it("parent-only folds report nothing, and each note reads once", () => {
    fc.assert(
      fc.property(scenario, ({ toolTurns, folds }) => {
        const doorsOnly = drive(toolTurns, []);
        const embedded = drive(toolTurns, folds);

        // The run went where the scenario says, ending on its answer.
        expect(doorsOnly.settled).toBe(true);

        // One event per note: a brain start per turn asked for, a tool start
        // per call, a failure per failing call, one ending.
        const count = (type: AgentEvent<string>["type"]) =>
          doorsOnly.stream.filter((e) => e.type === type).length;
        const calls = toolTurns.flat();
        expect(count("BrainStarted")).toBe(toolTurns.length + 1);
        expect(count("ToolStarted")).toBe(calls.length);
        expect(count("ToolFailed")).toBe(calls.filter((ok) => !ok).length);
        expect(count("RunDone")).toBe(1);

        // A parent's own transition reports none of them again.
        expect(embedded.fromFolds).toEqual([]);
        expect(embedded.stream).toEqual(doorsOnly.stream);
      }),
      { numRuns: 200 },
    );
  });
});

import type { HrTime } from "@opentelemetry/api";
import {
  BasicTracerProvider,
  InMemorySpanExporter,
  SimpleSpanProcessor,
} from "@opentelemetry/sdk-trace-base";
import fc from "fast-check";
import { describe, expect, it } from "vitest";
import type { AgentEvent } from "../agent/index";
import { agentSpans } from "./index";

// ---------------------------------------------------------------------------
// Promise: a span's start and end are the run clock's instant, however long
// the process has been up. `at` is epoch ms; OTel must never rebase it onto
// `performance.timeOrigin` because it happens to be <= `performance.now()`.
// ---------------------------------------------------------------------------

const hr = (ms: number): HrTime => [Math.trunc(ms / 1e3), (ms % 1e3) * 1e6];

function tracer() {
  const exporter = new InMemorySpanExporter();
  const provider = new BasicTracerProvider({
    spanProcessors: [new SimpleSpanProcessor(exporter)],
  });
  return { exporter, tracer: provider.getTracer("span-time-promise") };
}

// Clock values both below the process's uptime (the range OTel would read as
// performance-relative) and in the epoch-ms range a `Date.now()` clock gives.
const instant = () =>
  fc.oneof(
    fc.integer({ min: 0, max: Math.max(0, Math.floor(performance.now()) - 1) }),
    fc.integer({ min: 0, max: 100_000 }),
    fc.integer({ min: 1_500_000_000_000, max: 2_500_000_000_000 }),
  );

describe("span time is the run clock's instant", () => {
  it("every span starts and ends at the exact HrTime of its event's `at`", () => {
    fc.assert(
      fc.property(
        instant(),
        fc.array(fc.integer({ min: 0, max: 5_000 }), {
          minLength: 4,
          maxLength: 4,
        }),
        (start, steps) => {
          const [d1 = 0, d2 = 0, d3 = 0, d4 = 0] = steps;
          const brainAt = start + d1;
          const settledAt = brainAt + d2;
          const toolAt = settledAt + d3;
          const doneAt = toolAt + d4;
          const toolEndAt = doneAt;
          const runId = "run-time";
          const { exporter, tracer: t } = tracer();
          const spans = agentSpans<string>({ tracer: t, name: "clock" });
          const events: AgentEvent<string>[] = [
            {
              type: "BrainStarted",
              runId,
              at: brainAt,
              turn: 0,
              purpose: "act",
              model: "m",
              payload: {},
            },
            {
              type: "TurnSettled",
              runId,
              at: settledAt,
              turn: { content: "x", toolCalls: [] },
            },
            {
              type: "ToolStarted",
              runId,
              at: toolAt,
              callId: "c1",
              name: "probe",
              args: {},
            },
            {
              type: "ToolSettled",
              runId,
              at: toolEndAt,
              callId: "c1",
              result: "ok",
            },
            {
              type: "RunDone",
              runId,
              at: doneAt,
              status: { kind: "done", output: null },
            },
          ];
          for (const e of events) spans.onEvent(e);
          spans.end();

          const finished = exporter.getFinishedSpans();
          const named = (n: string) => {
            const s = finished.find((x) => x.name === n);
            if (s === undefined) throw new Error(`no span ${n}`);
            return s;
          };
          const root = named("invoke_agent clock");
          const brain = named("chat m");
          const tool = named("execute_tool probe");

          // The run span opens on the first event it sees.
          expect(root.startTime).toEqual(hr(brainAt));
          expect(root.endTime).toEqual(hr(doneAt));
          expect(brain.startTime).toEqual(hr(brainAt));
          expect(brain.endTime).toEqual(hr(settledAt));
          expect(tool.startTime).toEqual(hr(toolAt));
          expect(tool.endTime).toEqual(hr(toolEndAt));
        },
      ),
      { numRuns: 200 },
    );
  });
});

import fc from "fast-check";
import { afterEach, describe, expect, it, vi } from "vitest";
import {
  fetchPost as backlogFetchPost,
  httpJevClient as backlogHttpJevClient,
} from "../../backlog-sweep/src/jev.js";
import { questions as backlogQuestions } from "../../backlog-sweep/src/verdict.js";
import { fetchPost, httpJevClient } from "../src/jev.js";
import { pairQuestions } from "../src/pairs/questions.js";

// Promise: a Jev client error never carries the API key — not in the error body
// `fetchPost` hands back for a status >= 400, and not in the `JevAskError` the
// client throws from it, even when the upstream body echoes the key.

const clients = [
  {
    name: "structure-sweep",
    fetchPost,
    ask: (post: ReturnType<typeof fetchPost>) =>
      httpJevClient({ questions: pairQuestions, model: "jev-1", post, ...fast }),
  },
  {
    name: "backlog-sweep",
    fetchPost: backlogFetchPost,
    ask: (post: ReturnType<typeof backlogFetchPost>) =>
      backlogHttpJevClient({
        questions: backlogQuestions,
        model: "jev-1",
        post,
        ...fast,
      }),
  },
] as const;

const fast = {
  sleep: async () => {},
  retry: {
    baseMs: 1,
    factor: 2,
    capMs: 1,
    maxAttempts: 2,
    jitter: "none",
  },
} as const;

/** A made-up key: a fixed prefix no generated filler contains, then random characters. */
const fakeKey = fc
  .stringMatching(/^[A-Za-z0-9_-]{16,40}$/)
  .map((tail) => `tsk_FAKE_${tail}`);

const filler = fc.string({ maxLength: 12 }).filter((s) => !s.includes("tsk_"));

/** A string that may echo the key, with text either side of it. */
const echoing = (key: string) =>
  fc.oneof(
    filler,
    fc.constant(key),
    fc.tuple(filler, filler).map(([a, b]) => `${a}${key}${b}`),
    fc
      .tuple(filler, filler)
      .map(([a, b]) => `${a}Bearer ${key} and again ${key}${b}`),
  );

/** A JSON error body shaped like a provider error, with the key echoed anywhere in its values. */
const errorBody = (key: string) => {
  const leaf = fc.oneof(
    echoing(key),
    fc.integer(),
    fc.boolean(),
    fc.constant(null),
  );
  const { tree } = fc.letrec((tie) => ({
    tree: fc.oneof(
      { depthSize: "small", withCrossShrink: true },
      leaf,
      fc.array(tie("tree"), { maxLength: 3 }),
      fc.dictionary(
        fc.string({ maxLength: 6 }).filter((k) => !k.includes("tsk_")),
        tie("tree"),
        { maxKeys: 3 },
      ),
    ),
  }));
  return fc.record(
    {
      error: fc.record(
        { message: echoing(key), code: echoing(key), type: echoing(key) },
        { requiredKeys: [] },
      ),
      request: fc.record(
        {
          headers: fc.record({ authorization: echoing(key) }),
          extra: tree,
        },
        { requiredKeys: [] },
      ),
    },
    { requiredKeys: [] },
  );
};

const status = fc.oneof(
  fc.constantFrom(400, 401, 402, 403, 404, 422, 429, 500, 529),
  fc.integer({ min: 400, max: 599 }),
);

const scenario = fakeKey.chain((key) =>
  fc.record({ key: fc.constant(key), status, body: errorBody(key) }),
);

function serveOnce(reply: { status: number; body: unknown }) {
  vi.stubGlobal(
    "fetch",
    vi.fn(
      async () =>
        new Response(JSON.stringify(reply.body), {
          status: reply.status,
          headers: { "content-type": "application/json" },
        }),
    ),
  );
}

/** Everything an error can show: its message, its string form and its own fields. */
function exposed(error: unknown): string {
  if (!(error instanceof Error)) return String(error);
  const fields: Record<string, unknown> = {};
  for (const name of Object.getOwnPropertyNames(error)) {
    if (name === "stack") continue;
    fields[name] = (error as unknown as Record<string, unknown>)[name];
  }
  return [error.message, String(error), JSON.stringify(fields)].join("\n");
}

afterEach(() => {
  vi.unstubAllGlobals();
});

describe("a Jev client error never carries the API key", () => {
  for (const client of clients) {
    it(`${client.name}: fetchPost's error body for a status >= 400 holds no key`, async () => {
      await fc.assert(
        fc.asyncProperty(scenario, async ({ key, status, body }) => {
          serveOnce({ status, body });
          const reply = await client.fetchPost(key)({
            state: {},
            model: "jev-1",
            questions: {},
          });
          expect(reply.status).toBe(status);
          expect(JSON.stringify(reply.body) ?? "").not.toContain(key);
        }),
        { numRuns: 200 },
      );
    });

    it(`${client.name}: the thrown JevAskError holds no key`, async () => {
      await fc.assert(
        fc.asyncProperty(scenario, async ({ key, status, body }) => {
          serveOnce({ status, body });
          const ask = client.ask(client.fetchPost(key));
          const thrown = await ask({ a: 1 }).then(
            () => undefined,
            (error: unknown) => error,
          );
          expect(thrown).toBeInstanceOf(Error);
          expect(exposed(thrown)).not.toContain(key);
        }),
        { numRuns: 200 },
      );
    });
  }
});
